<script>
import { defineAsyncComponent } from 'vue';
import { lockBodyScroll } from '../../utils/bodyScrollLock';
import GalleryMark from './GalleryMark.vue';
import AiViewTerm from '../ui/AiViewTerm.vue';
import ViewAboutContent from './ViewAboutContent.vue';
import MuseumFloorPlan from './MuseumFloorPlan.vue';
import GalleryFilm from '../ui/GalleryFilm.vue';
import GalleryDesignLink from './GalleryDesignLink.vue';
import { initialExhibitionDarkMode } from '../../utils/exhibitionTheme';
import { initDialogBackdrop } from '../../utils/dialogBackdrop';
import { animateGalleryDialog } from '../../utils/galleryDialogMotion';

const mediaPreferenceKey = 'gallery-info-media';
let rememberedMedia = 'film';
function initialMedia() {
  try {
    const saved = localStorage.getItem(mediaPreferenceKey);
    if (saved === 'film' || saved === 'plan') rememberedMedia = saved;
  } catch { /* Retain the choice for this visit when storage is unavailable. */ }
  return rememberedMedia;
}

export default {
  name: 'PublicViewsInfoDialog',
  components: { GalleryMark, AiViewTerm, ViewAboutContent, MuseumFloorPlan, GalleryFilm, GalleryDesignLink, MuseumDesignDialog: defineAsyncComponent(() => import('./MuseumDesignDialog.vue')) },
  props: { note: Boolean, museum: Boolean, centred: Boolean, dark: Boolean, area: {type:String,default:'hall'}, tourAvailable: { type: Boolean, default: true } },
  emits: ['close','tour','navigate','design'],
  data:()=>({viewportStyle:{},closing:false,designOpen:false,designDark:false,media:initialMedia(),mediaTabs:[{id:'film',label:'Introduction'},{id:'plan',label:'Floor plan'}]}),
  methods:{
    selectMedia(id){
      this.media=id;rememberedMedia=id;
      try{localStorage.setItem(mediaPreferenceKey,id);}catch{ /* The in-memory choice remains available. */ }
    },
    mediaKey(event,index){
      const count=this.mediaTabs.length;
      const keys={ArrowRight:(index+1)%count,ArrowLeft:(index+count-1)%count,Home:0,End:count-1};
      if(!(event.key in keys))return;
      event.preventDefault();
      const id=this.mediaTabs[keys[event.key]].id;
      this.selectMedia(id);
      this.$nextTick(()=>this.$refs.dialog.querySelector(`#gallery-info-tab-${id}`).focus());
    },
    openDesign(){if(this.museum)this.leave('design');else{this.designDark=initialExhibitionDarkMode();this.designOpen=true;}},
    async leave(event='close',payload){
      if(this.closing)return;
      this.closing=true;
      if(this.museum){
        this._exit=animateGalleryDialog(this.$refs.dialog,false,this._entrance);
        await this._exit?.finished.catch(()=>{});
      }
      if(!this._destroyed)this.$emit(event,payload);
    },
    syncViewport(){const v=window.visualViewport,w=v?.width||window.innerWidth,h=v?.height||window.innerHeight;this.viewportStyle={'--dialog-centre-x':`${(v?.offsetLeft||0)+w/2}px`,'--dialog-centre-y':`${(v?.offsetTop||0)+h/2}px`,'--dialog-height':`${h}px`,'--dialog-width':`${w}px`};}},
  mounted() {
    this.syncViewport();
    this._viewport=window.visualViewport;
    this._viewport?.addEventListener('resize',this.syncViewport);this._viewport?.addEventListener('scroll',this.syncViewport);window.addEventListener('resize',this.syncViewport);
    this._trigger = document.activeElement;
    this._releaseScroll = lockBodyScroll();
    this.$refs.dialog.showModal();
    if (this.museum) this._entrance = animateGalleryDialog(this.$refs.dialog,true);
    this._stopBackdrop = initDialogBackdrop(this.$refs.dialog, () => this.leave('close'));
    this.$refs.close.focus({ preventScroll: true });
  },
  beforeUnmount() {
    this._destroyed=true;this._exit?.cancel();
    this._viewport?.removeEventListener('resize',this.syncViewport);this._viewport?.removeEventListener('scroll',this.syncViewport);window.removeEventListener('resize',this.syncViewport);
    this._entrance?.cancel();
    this._stopBackdrop?.();
    this.$refs.dialog?.close();
    this._releaseScroll?.();
    if (this._trigger?.isConnected) this._trigger.focus({ preventScroll: true });
  },
};
</script>

