<template>
  <main class="mono-home" :class="{'mono-dark': dark, 'mono-reduced': reduced, 'mono-asking': askOpen, 'mono-opening': opening, 'mono-tab-arrival': tabArrival, 'mono-answer-arriving': answerArriving, 'mono-answer-arrival-ready': answerArrivalReady, 'mono-opening-pending': opening&&!openingChrome, 'mono-opening-ask': opening&&openingAsk, 'mono-opening-chrome': opening&&openingChrome, 'mono-cue-breathing': cueBreathing}" data-image-enlarge="off">
    <section ref="hello" class="mono-hello" aria-label="Henry Wang">
      <span id="story-about" class="mono-about-anchor" data-story-chapter="About" aria-hidden="true"></span>
      <div ref="helloStage" class="mono-pin mono-hello-stage" data-home-motion-stage>
        <div ref="viewport" class="mono-hello-viewport">
          <h1 class="mono-name" :style="nameStyle" aria-label="Henry Wang"><span class="mono-name-word" :style="firstStyle" aria-hidden="true"><span class="mono-name-measure">Henry</span><span class="mono-name-typed" :class="{'has-caret':opening&&!openingAsk&&typedCount<6}">{{'Henry'.slice(0,typedCount)}}</span></span><span class="mono-name-word" :style="lastStyle" aria-hidden="true"><span class="mono-name-measure">Wang</span><span class="mono-name-typed" :class="{'has-caret':opening&&!openingAsk&&typedCount>=6&&typedCount<10}">{{'Wang'.slice(0,Math.max(0,typedCount-6))}}</span></span></h1>
          <HomeAsk class="mono-opening-foot" :style="{opacity:askEditing?1:1-phase(p.hello,.03,.14)}" :inert="(opening&&!openingAsk)||(!askEditing&&!reduced&&p.hello>.14)" @engaged="setAsking" @editing="askEditing=true"/>
          <button class="mono-continue" :style="{opacity:1-phase(p.hello,.01,.12)}" :inert="(opening&&!openingChrome)||p.hello>.12" @click="go('hello',.88,1500)"><span>Scroll to explore</span><svg viewBox="0 0 20 28" aria-hidden="true"><path d="M10 1v24m-5-5 5 5 5-5"/></svg></button>
        </div>
        <div class="mono-intro" :style="introLayoutStyle">
          <div class="mono-print-slot">
            <figure class="mono-print" :style="printStyle" :inert="!introVisible">
              <img src="/assets/img/henry-rooftop-portrait.jpg" width="1011" height="1404" alt="Henry on a rooftop at sunset" fetchpriority="high" decoding="async"/>
              <figcaption :style="{opacity:reduced?1:phase(settle,.5,.9)}"><HomeWelcomeAudio :active="introVisible"/></figcaption>
            </figure>
          </div>
          <div class="mono-bio" :style="bioStyle" :inert="!introVisible">
            <h2>I'm Henry Han-yu Wang.</h2>
            <p>I was born in <router-link class="mono-place-link" to="/travels#tainan">Taiwan</router-link>, grew up in <router-link class="mono-place-link" to="/travels#shanghai">Shanghai</router-link>, and now study Applied AI at the University of <router-link class="mono-place-link" to="/travels#hong-kong">Hong Kong</router-link>. Alongside my studies, I work in AI consulting at PwC.</p>
            <p>I explore ideas and develop models to understand how things work. When I see a way to put that understanding to use, I design and build something around it.</p>
            <HomePreviewLink to="/cv" label="CV" class="mono-link">CV<ArrowUpRightIcon/></HomePreviewLink>
          </div>
        </div>
      </div>
    </section>

    <section id="story-research" data-story-chapter="Research" ref="research" class="mono-research">
      <div class="mono-research-content">
        <h2><span class="mono-line"><span :style="lineStyle('research',0)">I study how people</span></span><span class="mono-line"><span :style="lineStyle('research',.13)">and machines learn.</span></span></h2>
        <div class="mono-research-body" :style="arrivalStyle('research',.25)"><p>My research explores how people and AI systems learn from experience and use their knowledge. I also examine how interacting with AI shapes the way we think and learn.</p><HomePreviewLink to="/research" label="Research" class="mono-link">Explore my research<ArrowUpRightIcon/></HomePreviewLink></div>
      </div>
    </section>

    <section id="story-builds" data-story-chapter="Builds" ref="work" class="mono-work" aria-label="Selected projects">
      <div class="mono-pin mono-work-stage" data-home-motion-stage>
        <div class="mono-work-heading" :style="arrivalStyle('work',0)"><h2>I design and build systems<br>that put AI to practical use.</h2><HomePreviewLink to="/projects" label="Builds" class="mono-link">All builds<ArrowUpRightIcon/></HomePreviewLink></div>
        <div class="mono-screening" :class="{'is-switching':projectJump!==null}" :style="screeningArrival">
          <div class="mono-work-screen">
            <article v-for="(item,i) in projects" :key="item.title" class="mono-work-plane" :class="{'mono-active':selected===i}" :style="workStyle(i)" :inert="selected!==i" :aria-hidden="selected!==i">
              <button class="mono-work-open" :aria-label="`Watch ${item.title}`" @click="openFilm(i)" @pointerenter="hovered=i" @pointerleave="hovered=-1" @focus="hovered=i" @blur="hovered=-1">
                <div class="mono-work-image">
                  <template v-if="i===0"><div class="mono-gallery-brand"><span class="mono-gallery-title"><GalleryMark/>The View Gallery</span><span class="mono-gallery-sub">Part of the project AI × Self</span></div><GalleryBuildingMark :active="hovered===0" :dark="dark"/></template>
                  <template v-else-if="i===1"><span class="mono-cathay-brand" aria-hidden="true"></span><span class="mono-cathay-slogan">Let your flexibility take you further.</span></template>
                  <SlidePoiseFilmCover v-else/>
                </div>
                <span class="mono-play"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="m9 6 9 6-9 6Z"/></svg><span>Watch video<small>{{item.duration}}</small></span></span>
              </button>
            </article>
          </div>
          <div class="mono-work-notes">
            <nav aria-label="Select a project"><button v-for="(item,i) in projects" :key="item.title" :aria-pressed="selected===i" @click="selectWork(i)"><span>0{{i+1}}</span>{{item.title}}</button></nav>
            <div class="mono-work-descriptions"><div v-for="(item,i) in projects" :key="item.title" class="mono-work-description" :class="{'is-current':selected===i}" :inert="selected!==i" :aria-hidden="selected!==i"><p>{{item.description}}</p><router-link v-if="item.href.startsWith('#/')" class="mono-link" :to="item.href.slice(1)">Explore the project<ArrowUpRightIcon/></router-link><a v-else class="mono-link" :href="item.href" target="_blank" rel="noopener">Explore the project<ArrowUpRightIcon/></a><router-link v-if="i===0" to="/views?presentation=museum" class="mono-link mono-gallery-link"><span>Explore the <ArchiveTerm kind="gallery"/></span><ArrowUpRightIcon/></router-link></div></div>
          </div>
        </div>
      </div>
    </section>

    <section id="story-life" data-story-chapter="Life" ref="sea" class="mono-sea">
      <div class="mono-pin mono-sea-stage" data-home-motion-stage>
        <div class="mono-sea-composition">
          <div class="mono-sea-copy"><h2><span class="mono-line"><span :style="lineStyle('sea',0)">I like the open</span></span><span class="mono-line"><span :style="lineStyle('sea',.08)">space by the sea.</span></span></h2><p :style="arrivalStyle('sea',.15)">My mother used to drive me to the coast near <router-link class="mono-place-link" to="/travels#napier">Napier</router-link>, where we would sit and watch the sea for hours. In <router-link class="mono-place-link" to="/travels#hong-kong">Hong Kong</router-link>, I spent evenings on the waterfront at Kennedy Town.</p></div>
          <CoastDevelopment :progress="coastProgress" :reduced="reduced" :dark="dark"/>
        </div>
      </div>
    </section>

    <section id="story-fragments" data-story-chapter="Fragments" ref="fragments" class="mono-fragments">
      <span id="showcaseimages" class="mono-fragments-anchor" aria-hidden="true"></span>
      <div class="mono-pin mono-fragments-stage" data-home-motion-stage>
        <div class="mono-photographs" aria-hidden="true"><figure v-for="(photo,i) in photos" :key="photo" :style="fragmentStyle(i)"><img :src="photo" alt="" loading="lazy" decoding="async"/></figure></div>
        <div class="mono-fragments-copy" :style="{opacity:reduced?1:smooth(phase(fragmentProgress,.4,.65))}" :inert="!reduced&&fragmentProgress<.6"><h2>I want to remember<br>what life felt like.</h2><p>As AI becomes part of everyday life, I value having a record of my own thoughts and feelings. Fragments is where I write some of them down.</p><HomePreviewLink to="/fragments" label="Fragments" class="mono-link">Read Fragments<ArrowUpRightIcon/></HomePreviewLink><HomePreviewLink to="/travels" label="Travels" class="mono-link">Explore Travels<ArrowUpRightIcon/></HomePreviewLink></div>
      </div>
    </section>

    <section id="story-contact" data-story-chapter="Contact" ref="contact" class="mono-contact" :style="arrivalStyle('contact',0)">
      <p>I'd love to hear from you.</p>
      <div class="mono-contact-actions"><button class="mono-say-hello" @click="openContact">Say hello<ArrowUpRightIcon/></button><div class="mono-addresses"><a aria-label="Personal messages to whenry6688@gmail.com" href="mailto:whenry6688@gmail.com">whenry6688@gmail.com</a><a aria-label="Academic matters to henry.why@connect.hku.hk" href="mailto:henry.why@connect.hku.hk">henry.why@connect.hku.hk</a></div></div>
    </section>

    <Teleport to="body">
      <dialog ref="dialog" class="mono-film" @click="backdrop" @keydown.esc.prevent="closeFilm" @close="film=null"><div class="mono-film-inner"><button ref="close" aria-label="Close video" @click="closeFilm"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="m5 5 14 14M19 5 5 19"/></svg></button><component v-if="film!==null" ref="filmPlayer" :is="projects[film].component" :dark="dark" :active="true" :unframed="true"/></div></dialog>

    </Teleport>
    <HomeContact ref="contactForm" :dark="dark"/>
  </main>
</template>

<script>
import GalleryFilm from '../../components/ui/GalleryFilm.vue';
import CathayFlexFilm from '../../components/ui/CathayFlexFilm.vue';
import SlidePoiseFilm from '../../components/ui/SlidePoiseFilm.vue';
import ArrowUpRightIcon from '../../components/ui/ArrowUpRightIcon.vue';
import HomeWelcomeAudio from '../../components/ui/HomeWelcomeAudio.vue';
import GalleryBuildingMark from '../../components/ui/GalleryBuildingMark.vue';
import GalleryMark from '../../components/view/GalleryMark.vue';
import ArchiveTerm from '../../components/ui/ArchiveTerm.vue';
import SlidePoiseFilmCover from '../../components/ui/SlidePoiseFilmCover.vue';
import CoastDevelopment from './CoastDevelopment.vue';
import HomeAsk, {hasSavedHomeAnswer} from './HomeAsk.vue';
import HomeContact from './HomeContact.vue';
import HomePreviewLink from './HomePreviewLink.vue';
import {watchHomeMotion,homeMotionSpan,glideHomeTo,phase,smooth,mix} from './homeMotion';
import {initialExhibitionDarkMode} from '../../utils/exhibitionTheme';
import {aboutGalleryPreview,pickHomeGalleryImages} from '../../data/aboutGallery';
import {claimHomeOpening,claimHomeTabOpening,playHomeOpening} from './homeOpening';
import {getRouteArrival} from '../../utils/routeScroll';
import {preloadHomePhotos} from './homePhotoPreload';
import './home.css';
const projects=[
  {title:'AI × Self',description:'Ask about my work and life. AI finds the relevant material in my archive and can turn your question into an exhibition.',href:'#/aipersonalarchive',component:'GalleryFilm',duration:'1 min 39 sec'},
  {title:'Cathay Flex',description:'An airline marketplace where travellers earn credits for accepting suitable seat or flight changes. AI and optimisation find arrangements that meet passengers’ preferences and the airline’s needs.',href:'https://cathayflex.github.io/',component:'CathayFlexFilm',duration:'2 min'},
  {title:'SlidePoise',description:'An open-source AI framework for creating editable PowerPoint decks. It develops slide designs with you, then reconstructs them as text, charts and shapes you can edit.',href:'https://slidepoise.github.io/',component:'SlidePoiseFilm',duration:'2 min 5 sec'},
];
const keys=['hello','research','work','sea','fragments','contact'];
const blankProgress=()=>Object.fromEntries(keys.map(k=>[k,0]));
export default{
  name:'HomePage',
  components:{HomeAsk,HomeContact,HomePreviewLink,ArchiveTerm,ArrowUpRightIcon,HomeWelcomeAudio,GalleryBuildingMark,GalleryMark,SlidePoiseFilmCover,CoastDevelopment,GalleryFilm,CathayFlexFilm,SlidePoiseFilm},
  data(){return{opening:false,tabArrival:false,answerArriving:false,answerArrivalReady:false,openingAsk:true,openingChrome:true,typedCount:10,cueBreathing:false,askOpen:hasSavedHomeAnswer(),askEditing:false,dark:initialExhibitionDarkMode(),reduced:matchMedia('(prefers-reduced-motion: reduce)').matches,width:innerWidth,height:innerHeight,p:blankProgress(),entry:blankProgress(),projects,film:null,hovered:-1,manualProject:0,projectJump:null,photos:pickHomeGalleryImages().map(aboutGalleryPreview)};},
  created(){
    const arrival={hash:this.$route.fullPath,chapter:this.$route.hash||this.$route.query.to,restored:this.askOpen,reduced:this.reduced,historyReturn:performance.getEntriesByType('navigation')[0]?.type==='back_forward'};
    const firstArrival=claimHomeOpening(arrival);
    this.tabArrival=claimHomeTabOpening(arrival);
    this.answerArriving=this.tabArrival&&this.askOpen;
    this.opening=firstArrival||(this.tabArrival&&!this.askOpen);
    if(this.opening){this.typedCount=0;this.openingAsk=false;this.openingChrome=false;}
  },
  computed:{
    mobile(){return this.width<=760;},
    reveal(){return this.askEditing?0:smooth(phase(this.p.hello,.03,.38));},
    settle(){return smooth(phase(this.p.hello,.4,.75));},
    introVisible(){return this.reduced||this.p.hello>.65;},
    nameStyle(){return{opacity:this.askEditing?1:1-smooth(phase(this.p.hello,this.askOpen?.03:.33,this.askOpen?.18:.46))};},
    firstStyle(){return{transform:`translate3d(${this.askOpen?0:-this.reveal*this.width*.4}px,0,0)`};},
    lastStyle(){return{transform:`translate3d(${this.askOpen?0:this.reveal*this.width*.4}px,0,0)`};},
    introLayout(){
      const width=Math.min(this.width*.46,this.height*.23);
      return{width,height:width*1404/1011+73,top:Math.max(72,Math.min(100,this.height*.1))};
    },
    introLayoutStyle(){return{'--intro-print-width':`${this.introLayout.width+22}px`,'--intro-print-height':`${this.introLayout.height}px`,'--intro-top':`${this.introLayout.top}px`};},
    printStyle(){
      if(this.reduced)return{};
      const s=this.settle;
      const w=this.mobile?this.introLayout.width:Math.min(this.width*.25,this.height*.4,390);
      const initial=this.mobile?Math.min(this.width*.68,this.height*.34):Math.min(this.width*.38,this.height*.5);
      const y=this.mobile?mix(this.height/2-this.introLayout.top-this.introLayout.height/2,0,s):0;
      const x=mix(0,this.mobile?0:-this.width*.23,s);
      return{
        width:`${mix(initial,w,s)}px`,opacity:this.reveal>0?1:0,
        clipPath:this.reveal>=.999?'none':`inset(0 ${(1-this.reveal)*50}% 0)`,
        transform:`translate(calc(-50% + ${x}px),calc(-50% + ${y}px))`,
        padding:`${mix(0,11,s)}px`,paddingBottom:`${mix(0,62,s)}px`,
      };
    },
    bioStyle(){return this.reduced?{}:{opacity:smooth(phase(this.p.hello,.61,.79)),clipPath:`inset(0 0 ${(1-smooth(phase(this.p.hello,.58,.78)))*100}% 0)`};},
    workPosition(){return phase(this.p.work,.12,.87)*2;},
    selected(){return this.reduced?this.manualProject:this.projectJump??Math.round(this.workPosition);},
    screeningArrival(){if(this.reduced)return{};const a=smooth(phase(this.entry.work,.05,.86));return{clipPath:`inset(${(1-a)*28}% ${(1-a)*8}% 0)`,transform:`perspective(1400px) rotateX(${(1-a)*8}deg)`,opacity:smooth(phase(this.entry.work,0,.35))};},
    coastProgress(){
      // Finish the contours on arrival, then develop the image during the pinned scroll.
      const drawing=.24*smooth(phase(this.entry.sea,.12,.88));
      return drawing+.76*phase(this.p.sea,.08,.78);
    },
    fragmentProgress(){return Math.min(1,this.entry.fragments*.18+this.p.fragments*.82);},
  },
  watch:{'$route.path'(){this.$nextTick(()=>window.dispatchEvent(new Event('home-entrance-prepared')));}},
  mounted(){
    this.cancelPhotoPreload=preloadHomePhotos(this.$refs.fragments.querySelectorAll('.mono-photographs img'));
    // Reserve the complete introduction before measuring any chapter destinations.
    const sizeIntroduction=()=>{
      this.width=this.$refs.viewport.clientWidth;
      this.height=this.$refs.viewport.clientHeight;
      const height=`${this.$refs.helloStage.getBoundingClientRect().height}px`;
      if(this.$refs.hello.style.getPropertyValue('--hello-stage-height')!==height)this.$refs.hello.style.setProperty('--hello-stage-height',height);
    };
    sizeIntroduction();
    this.introResize=new ResizeObserver(()=>{
      cancelAnimationFrame(this.introResizeFrame);
      this.introResizeFrame=requestAnimationFrame(sizeIntroduction);
    });
    this.introResize.observe(this.$refs.helloStage);
    this.introResize.observe(this.$refs.viewport);
    this.startOpening();this.$nextTick(()=>window.dispatchEvent(new Event('home-entrance-prepared')));this.cleanup=watchHomeMotion(keys.map(k=>this.$refs[k]),(values,reduced,entries)=>{keys.forEach((k,i)=>{this.p[k]=values[i];this.entry[k]=entries[i];});this.reduced=reduced;},this.$refs.viewport);this.themeChange=()=>{this.dark=initialExhibitionDarkMode();};addEventListener('theme-change',this.themeChange);this.releaseAskEditing=()=>{this.askEditing=false;this.projectJump=null;};this.releaseProjectKeys=e=>{if(!e.target.closest('input,textarea')&&['ArrowDown','ArrowUp','PageUp','PageDown','Home','End',' '].includes(e.key))this.projectJump=null;};addEventListener('keydown',this.releaseProjectKeys);addEventListener('wheel',this.releaseAskEditing,{passive:true});addEventListener('touchmove',this.releaseAskEditing,{passive:true});},
  beforeUnmount(){this.openingDisposed=true;this.cancelPhotoPreload?.();clearTimeout(this.answerArrivalTimer);this.introResize?.disconnect();cancelAnimationFrame(this.introResizeFrame);this.cancelOpening?.();this.cancelGlide?.();this.cleanup?.();removeEventListener('keydown',this.releaseProjectKeys);removeEventListener('theme-change',this.themeChange);removeEventListener('wheel',this.releaseAskEditing);removeEventListener('touchmove',this.releaseAskEditing);this.$refs.dialog?.close();},
  methods:{
    phase,smooth,
    async startOpening(){
      if(!this.opening&&!this.answerArriving)return;
      if(this.tabArrival){
        // Let the router finish its landing before observing scroll or typing.
        await getRouteArrival(this.$route.fullPath)?.ready;
        await new Promise(resolve=>requestAnimationFrame(resolve));
        if(this.openingDisposed)return;
      }
      if(this.answerArriving){
        this.answerArrivalReady=true;
        this.answerArrivalTimer=setTimeout(()=>{this.answerArriving=false;this.answerArrivalReady=false;},460);
        return;
      }
      this.cancelOpening=playHomeOpening(this.$el,{mode:this.tabArrival?'tab':'intro',onType:count=>{this.typedCount=count;},onAsk:()=>{this.openingAsk=true;},onChrome:()=>{this.openingChrome=true;},onBreathe:()=>{this.cueBreathing=true;},onFinish:()=>{this.opening=false;this.typedCount=10;this.openingAsk=true;this.openingChrome=true;this.cueBreathing=false;}});
    },
    setAsking(open){this.askOpen=open;if(open){this.askEditing=false;this.cancelOpening?.();this.cancelGlide?.();scrollTo({top:0,behavior:'instant'});}},
    go(name,p=0,duration=0){this.cancelGlide?.();this.askEditing=false;const e=this.$refs[name],top=e.getBoundingClientRect().top+scrollY+homeMotionSpan(e,this.height)*p;if(duration&&!this.reduced)this.cancelGlide=glideHomeTo(top,duration,this.$refs.viewport);else scrollTo({top,behavior:this.reduced?'instant':'smooth'});},
    lineStyle(section,delay){if(this.reduced)return{};const a=smooth(phase(this.entry[section],.08+delay,.78+delay));return{transform:`translateY(${(1-a)*102}%)`,opacity:phase(a,0,.35)};},
    arrivalStyle(section,delay=0){if(this.reduced)return{};const a=smooth(phase(this.entry[section],.05+delay,.7+delay));return{opacity:a,clipPath:`inset(0 0 ${(1-a)*100}% 0)`,transform:`translateY(${(1-a)*20}px)`};},
    selectWork(i){if(i===this.selected)return;this.manualProject=i;this.projectJump=i;if(!this.reduced)this.go('work',.12+i*.375);},
    workStyle(i){const weight=this.reduced||this.projectJump!==null?Number(this.selected===i):smooth(Math.max(0,1-Math.abs(i-this.workPosition)));return{opacity:weight,zIndex:this.selected===i?2:1,pointerEvents:this.selected===i?'auto':'none',transform:`scale(${mix(.98,1,weight)})`};},
    fragmentStyle(i){if(this.reduced)return{};const p=smooth(phase(this.fragmentProgress,.05,.82)),col=i%4,row=i<4?-1:1;const x=mix((i-3.5)*(this.mobile?32:18),(col-1.5)*(this.mobile?31:26),p);const y=mix(0,row*(this.mobile?32:37)+(col%2?1:-1),p);return{transform:`translate(-50%,-50%) translate(${x}vw,${y}svh)`,width:`${mix(this.mobile?30:16,this.mobile?29:(i%3===0?19:23),p)}vw`,height:`${mix(this.mobile?24:29,this.mobile?21:(i%3===0?26:22),p)}svh`,opacity:mix(1,.85,p)};},
    async openFilm(i){this.returnFocus=document.activeElement;this.film=i;await this.$nextTick();this.$refs.dialog.showModal();this.$refs.close.focus();await this.$nextTick();this.$refs.filmPlayer?.play();},
    closeFilm(){this.$refs.dialog.close();this.film=null;this.returnFocus?.focus({preventScroll:true});},
    backdrop(e){if(e.target===this.$refs.dialog)this.closeFilm();},
    openContact(){this.$refs.contactForm.open();},
  },
};
</script>
